from __future__ import annotations

import pytest

from app.workflows.codegen.nodes import route_orchestrator
from app.workflows.codegen.state import OrchestratorRoute, TaskRoute
from app.workflows.codegen.subgraph import (
    _route_after_critic,
    _route_after_tool_check,
    _route_after_reduce_with_cap,
    _ROUTE_TO_DEVELOPER,
    _ROUTE_TO_PROCEED_REVIEW,
    _ROUTE_TO_FAN_OUT,
)


