# ===========================================================================
# route_orchestrator
# ===========================================================================

class TestRouteOrchestrator:

    def test_error_routes_to_fail(self):
        state = _orch_state(error="Something went wrong.")
        assert route_orchestrator(state) == OrchestratorRoute.FAIL

    def test_no_tasks_routes_to_bundle(self):
        state = _orch_state(tasks=[], current_task_index=0)
        assert route_orchestrator(state) == OrchestratorRoute.BUNDLE

    def test_index_at_zero_with_tasks_routes_to_execute(self):
        state = _orch_state(
            tasks=[{"id": "t1", "title": "Task 1"}],
            current_task_index=0,
        )
        assert route_orchestrator(state) == OrchestratorRoute.EXECUTE_TASK

    def test_index_in_middle_routes_to_execute(self):
        tasks = [{"id": f"t{i}", "title": f"Task {i}"} for i in range(5)]
        state = _orch_state(tasks=tasks, current_task_index=2)
        assert route_orchestrator(state) == OrchestratorRoute.EXECUTE_TASK

    def test_index_at_end_routes_to_bundle(self):
        tasks = [{"id": f"t{i}", "title": f"Task {i}"} for i in range(3)]
        state = _orch_state(tasks=tasks, current_task_index=3)
        assert route_orchestrator(state) == OrchestratorRoute.BUNDLE

    def test_index_past_end_routes_to_bundle(self):
        tasks = [{"id": "t1", "title": "Task 1"}]
        state = _orch_state(tasks=tasks, current_task_index=99)
        assert route_orchestrator(state) == OrchestratorRoute.BUNDLE

    def test_error_takes_priority_over_tasks(self):
        # Even with tasks remaining, error should route to FAIL
        tasks = [{"id": "t1", "title": "Task 1"}]
        state = _orch_state(
            tasks=tasks,
            current_task_index=0,
            error="Critical DB failure.",
        )
        assert route_orchestrator(state) == OrchestratorRoute.FAIL


# ===========================================================================
# route_after_reduce (via _route_after_reduce_with_cap)
# ===========================================================================

class TestRouteAfterReduce:

    def test_review_passed_routes_to_finalize(self):
        state = _task_state(review_passed=True, retry_count=0, max_retries=3)
        assert _route_after_reduce_with_cap(state) == TaskRoute.FINALIZE

    def test_review_failed_with_retries_remaining_routes_to_retry(self):
        state = _task_state(review_passed=False, retry_count=1, max_retries=3)
        assert _route_after_reduce_with_cap(state) == TaskRoute.RETRY

    def test_review_failed_at_cap_routes_to_fail(self):
        state = _task_state(review_passed=False, retry_count=4, max_retries=3)
        assert _route_after_reduce_with_cap(state) == TaskRoute.FAIL

    def test_review_failed_exactly_at_cap_routes_to_fail(self):
        # retry_count starts at 0; cap is max_retries.
        # reduce_verdicts_node increments retry_count on failure.
        # So retry_count=3 with max_retries=3 means cap is hit.
        state = _task_state(review_passed=False, retry_count=3, max_retries=3)
        # retry_count (3) > max_retries (3) is False — should still RETRY
        # Actually route_after_reduce checks: if retry_count <= max_retries → RETRY
        # So retry_count=3, max_retries=3 → RETRY (one more attempt)
        assert _route_after_reduce_with_cap(state) == TaskRoute.RETRY

    def test_review_failed_one_over_cap_routes_to_fail(self):
        state = _task_state(review_passed=False, retry_count=4, max_retries=3)
        assert _route_after_reduce_with_cap(state) == TaskRoute.FAIL

    def test_passed_true_regardless_of_retry_count(self):
        for retry_count in range(6):
            state = _task_state(review_passed=True, retry_count=retry_count, max_retries=3)
            assert _route_after_reduce_with_cap(state) == TaskRoute.FINALIZE


# ===========================================================================
# _route_after_critic
# ===========================================================================

class TestRouteAfterCritic:

    def test_no_feedback_routes_to_proceed_review(self):
        state = _task_state(critic_feedback=None)
        assert _route_after_critic(state) == _ROUTE_TO_PROCEED_REVIEW

    def test_empty_string_feedback_routes_to_proceed_review(self):
        # Empty string is falsy — critic passed
        state = _task_state(critic_feedback="")
        assert _route_after_critic(state) == _ROUTE_TO_PROCEED_REVIEW

    def test_feedback_present_routes_to_developer(self):
        state = _task_state(critic_feedback="Loop is unbounded — fix it.")
        assert _route_after_critic(state) == _ROUTE_TO_DEVELOPER

    def test_whitespace_only_feedback_routes_to_developer(self):
        # Whitespace-only is truthy — treated as feedback present
        state = _task_state(critic_feedback="   ")
        assert _route_after_critic(state) == _ROUTE_TO_DEVELOPER


# ===========================================================================
# _route_after_tool_check
# ===========================================================================

class TestRouteAfterToolCheck:

    def test_no_issues_routes_to_fan_out(self):
        state = _task_state(
            review_passed     = True,
            aggregated_feedback = None,
            retry_count       = 0,
            max_retries       = 3,
        )
        assert _route_after_tool_check(state) == _ROUTE_TO_FAN_OUT

    def test_issues_with_retries_remaining_routes_to_developer(self):
        state = _task_state(
            review_passed       = False,
            aggregated_feedback = "Missing ToolNode.",
            retry_count         = 1,
            max_retries         = 3,
        )
        assert _route_after_tool_check(state) == _ROUTE_TO_DEVELOPER

    def test_issues_with_cap_hit_routes_to_fail(self):
        state = _task_state(
            review_passed       = False,
            aggregated_feedback = "Still missing ToolNode.",
            retry_count         = 4,   # > max_retries=3
            max_retries         = 3,
        )
        assert _route_after_tool_check(state) == TaskRoute.FAIL

    def test_no_feedback_but_review_not_passed_routes_to_fan_out(self):
        # If aggregated_feedback is falsy, we treat it as no tool-check failure
        # even if review_passed is somehow False (shouldn't happen, but defensive).
        state = _task_state(
            review_passed       = False,
            aggregated_feedback = None,
            retry_count         = 0,
            max_retries         = 3,
        )
        assert _route_after_tool_check(state) == _ROUTE_TO_FAN_OUT
